import React, { useEffect, useRef, useState } from "react";
import { Link, useNavigate, useSearchParams } from "react-router-dom";
import {
  AlertTriangle,
  ArrowLeft,
  Loader2,
  MessageSquare,
  Package,
  RotateCw,
  Send,
  Store,
  Trash2,
  Upload,
  User as UserIcon
} from "lucide-react";
import { useAuth } from "./AuthContext";
import { useNotice } from "./NoticeContext";
import { apiFetch, getApiBase } from "./api";
import { CATEGORY_LABELS as PRODUCT_CATEGORY_LABELS } from "./catalog";
import { formatGhc } from "./money";
import { h, f } from "./h";
import { Field, GlassPanel, InlineNotice, SelectInput, TextArea } from "./ui";
import { BuyerLayout, CartDrawer } from "./screensBuyer";

/** Buyer-facing issue types (matches backend category enum). */
const BUYER_PROBLEMS = [
  { value: "item_not_delivered", label: "Item not delivered" },
  { value: "wrong_item_received", label: "Wrong item received" },
  { value: "fake_misleading_product", label: "Fake / misleading product" },
  { value: "seller_not_responding", label: "Seller not responding" },
  { value: "other", label: "Other" }
];

/** Vendor-facing issue types. */
const VENDOR_PROBLEMS = [
  { value: "buyer_no_show", label: "Buyer didn't show up" },
  { value: "payment_not_confirmed", label: "Payment not confirmed" },
  { value: "fraudulent_activity", label: "Fraudulent activity" },
  { value: "abuse_misconduct", label: "Abuse / misconduct" },
  { value: "other", label: "Other" }
];

function orderRef(id) {
  if (!id) return "";
  return `ORD${String(id).slice(-6).toUpperCase()}`;
}

function statusBadgeClass(status) {
  if (status === "delivered") return "bg-emerald-500/15 text-emerald-700 dark:text-emerald-300";
  if (status === "sent_for_delivery") return "bg-indigo-500/15 text-indigo-700 dark:text-indigo-300";
  if (status === "processing") return "bg-sky-500/15 text-sky-700 dark:text-sky-300";
  if (status === "paid") return "bg-teal-500/15 text-teal-700 dark:text-teal-300";
  if (status === "awaiting_vendor_payment") return "bg-amber-500/15 text-amber-700 dark:text-amber-300";
  if (status === "pending_payment") return "bg-slate-500/15 text-slate-700 dark:text-slate-300";
  return "bg-rose-500/15 text-rose-700 dark:text-rose-300";
}

function humanizeStatus(s) {
  return String(s || "")
    .replace(/_/g, " ")
    .replace(/\b\w/g, (c) => c.toUpperCase());
}

/**
 * Order Details card for the left column on the report page.
 * Mirrors the reference image: header, order id + status, line items, vendor/customer row, summary, action buttons.
 *
 * @param {{
 *   variant: "buyer" | "vendor",
 *   order: any,
 *   products: Record<string, any>,
 *   loading: boolean,
 *   err: string,
 *   onRefresh: () => void
 * }} props
 */
function OrderDetailsCard({ variant, order, products, loading, err, onRefresh }) {
  const nav = useNavigate();
  if (loading) {
    return h(
      GlassPanel,
      { className: "!p-6" },
      h("div", { className: "flex items-center gap-2 text-sm text-slate-500" }, [
        h(Loader2, { key: "i", className: "h-4 w-4 animate-spin" }),
        "Loading order…"
      ])
    );
  }
  if (err) {
    return h(GlassPanel, { className: "!p-6" }, h("p", { className: "text-sm text-rose-600" }, err));
  }
  if (!order) return null;

  const lines = order.items || [];
  const subtotal = Number(order.subtotal) || 0;
  const total = Number(order.total) || 0;
  const deliveryFee = Math.max(0, total - subtotal);

  const myLines =
    variant === "vendor"
      ? lines
      : lines;

  const firstLine = myLines[0];
  const firstSellerId = firstLine ? String(firstLine.sellerId || "") : "";
  const sellerContacts = order.sellerContacts || [];
  const vendorContact =
    firstSellerId && Array.isArray(sellerContacts)
      ? sellerContacts.find((s) => String(s.id) === firstSellerId) || sellerContacts[0]
      : null;
  const buyer = order.buyerContact || null;
  const buyerId = buyer && buyer.id ? String(buyer.id) : "";

  return h(GlassPanel, { className: "!border-white/10 !p-5 sm:!p-6" }, [
    h("div", { key: "head", className: "mb-4 flex items-center justify-between gap-3" }, [
      h(
        "button",
        {
          type: "button",
          onClick: () => nav(-1),
          className:
            "inline-flex h-9 w-9 items-center justify-center rounded-full border border-slate-200 bg-white text-slate-700 hover:bg-slate-50 dark:border-white/10 dark:bg-white/5 dark:text-slate-200",
          "aria-label": "Back"
        },
        h(ArrowLeft, { className: "h-4 w-4" })
      ),
      h(
        "h2",
        { className: "min-w-0 flex-1 text-center font-display text-lg font-bold text-slate-900 dark:text-white" },
        "Order Details"
      ),
      h(
        "button",
        {
          type: "button",
          onClick: onRefresh,
          className:
            "inline-flex h-9 w-9 items-center justify-center rounded-full border border-slate-200 bg-white text-slate-700 hover:bg-slate-50 dark:border-white/10 dark:bg-white/5 dark:text-slate-200",
          "aria-label": "Refresh"
        },
        h(RotateCw, { className: "h-4 w-4" })
      )
    ]),
    h("div", { key: "id", className: "mb-4 flex flex-wrap items-center justify-between gap-2" }, [
      h("div", null, [
        h("p", { className: "text-[10px] font-bold uppercase tracking-wider text-slate-500" }, "Order ID"),
        h("p", { className: "font-mono text-sm font-semibold text-slate-900 dark:text-white" }, `#${orderRef(order.id)}`)
      ]),
      h(
        "span",
        { className: `inline-flex rounded-full px-3 py-1 text-xs font-semibold ${statusBadgeClass(order.status)}` },
        humanizeStatus(order.status)
      )
    ]),
    h(
      "div",
      { key: "items", className: "space-y-3" },
      myLines.map((it) => {
        const p = it.productId ? products[String(it.productId)] : null;
        const img = p && p.imageUrls && p.imageUrls[0] ? p.imageUrls[0] : null;
        const lineTotal = (Number(it.unitPrice) || 0) * (Number(it.quantity) || 1);
        return h(
          "div",
          {
            key: it.productId || it.name,
            className: "flex items-start gap-4 rounded-2xl border border-slate-100 bg-white p-3 dark:border-white/5 dark:bg-white/[0.02]"
          },
          [
            img
              ? h(
                  "div",
                  {
                    key: "im",
                    className: "h-20 w-20 shrink-0 overflow-hidden rounded-xl border border-slate-100 bg-slate-50 dark:border-white/5 dark:bg-white/5"
                  },
                  h("img", { src: img, alt: "", className: "h-full w-full object-cover" })
                )
              : h(
                  "div",
                  {
                    key: "ph",
                    className: "flex h-20 w-20 shrink-0 items-center justify-center rounded-xl border border-slate-100 bg-slate-50 dark:border-white/5 dark:bg-white/5"
                  },
                  h(Package, { className: "h-8 w-8 text-slate-400" })
                ),
            h("div", { key: "txt", className: "min-w-0 flex-1" }, [
              h("p", { className: "font-display text-sm font-semibold text-slate-900 dark:text-white" }, it.name),
              p && p.category
                ? h("p", { className: "mt-0.5 text-xs text-slate-500" }, PRODUCT_CATEGORY_LABELS[p.category] || p.category)
                : null,
              h("div", { className: "mt-2 flex items-center justify-between text-sm" }, [
                h("span", { className: "font-semibold text-slate-900 dark:text-white" }, formatGhc(lineTotal)),
                h("span", { className: "text-xs text-slate-500" }, `Qty: ${it.quantity ?? 1}`)
              ])
            ])
          ].filter(Boolean)
        );
      })
    ),
    variant === "buyer" && vendorContact
      ? h(
          "div",
          {
            key: "vendor",
            className: "mt-4 flex flex-wrap items-center justify-between gap-3 rounded-2xl border border-slate-100 bg-white p-3 dark:border-white/5 dark:bg-white/[0.02]"
          },
          [
            h("div", { className: "flex min-w-0 items-center gap-3" }, [
              h(
                "div",
                {
                  className:
                    "flex h-11 w-11 items-center justify-center rounded-full bg-purple-500/15 text-purple-700 dark:text-purple-200"
                },
                h(Store, { className: "h-5 w-5" })
              ),
              h("div", { className: "min-w-0" }, [
                h("p", { className: "truncate text-sm font-semibold text-slate-900 dark:text-white" }, vendorContact.displayName || "Seller"),
                h("p", { className: "text-xs text-slate-500" }, "Vendor")
              ])
            ]),
            h(
              Link,
              {
                to: firstSellerId ? `/messages?peer=${encodeURIComponent(firstSellerId)}` : "/messages",
                className:
                  "inline-flex min-h-[40px] items-center justify-center gap-2 rounded-2xl bg-purple-700 px-4 text-sm font-semibold text-white shadow-sm hover:bg-purple-800"
              },
              [h(MessageSquare, { key: "i", className: "h-4 w-4" }), "Chat"]
            )
          ]
        )
      : null,
    variant === "vendor" && buyer
      ? h(
          "div",
          {
            key: "cust",
            className: "mt-4 flex flex-wrap items-center justify-between gap-3 rounded-2xl border border-slate-100 bg-white p-3 dark:border-white/5 dark:bg-white/[0.02]"
          },
          [
            h("div", { className: "flex min-w-0 items-center gap-3" }, [
              h(
                "div",
                {
                  className:
                    "flex h-11 w-11 items-center justify-center rounded-full bg-violet-500/15 text-violet-700 dark:text-violet-200"
                },
                h(UserIcon, { className: "h-5 w-5" })
              ),
              h("div", { className: "min-w-0" }, [
                h("p", { className: "truncate text-sm font-semibold text-slate-900 dark:text-white" }, buyer.displayName || buyer.email || "Buyer"),
                h("p", { className: "text-xs text-slate-500" }, "Customer")
              ])
            ]),
            h(
              Link,
              {
                to: buyerId ? `/vendor/messages?peer=${encodeURIComponent(buyerId)}` : "/vendor/messages",
                className:
                  "inline-flex min-h-[40px] items-center justify-center gap-2 rounded-2xl bg-purple-700 px-4 text-sm font-semibold text-white shadow-sm hover:bg-purple-800"
              },
              [h(MessageSquare, { key: "i", className: "h-4 w-4" }), "Chat"]
            )
          ]
        )
      : null,
    h(
      "div",
      {
        key: "sum",
        className: "mt-4 rounded-2xl border border-slate-100 bg-white p-4 dark:border-white/5 dark:bg-white/[0.02]"
      },
      [
        h("p", { className: "text-[10px] font-bold uppercase tracking-wider text-slate-500" }, "Order Summary"),
        h("div", { className: "mt-3 space-y-2 text-sm" }, [
          h("div", { className: "flex items-center justify-between text-slate-600 dark:text-slate-300" }, [
            h("span", null, "Subtotal"),
            h("span", { className: "font-medium text-slate-900 dark:text-white" }, formatGhc(subtotal))
          ]),
          h("div", { className: "flex items-center justify-between text-slate-600 dark:text-slate-300" }, [
            h("span", null, "Delivery Fee"),
            h("span", { className: "font-medium text-slate-900 dark:text-white" }, formatGhc(deliveryFee))
          ]),
          h(
            "div",
            { className: "mt-1 flex items-center justify-between border-t border-slate-100 pt-3 text-base font-bold text-slate-900 dark:border-white/10 dark:text-white" },
            [h("span", null, "Total"), h("span", null, formatGhc(total))]
          )
        ])
      ]
    ),
    h("div", { key: "actions", className: variant === "buyer" ? "mt-4 grid grid-cols-1 gap-3 sm:grid-cols-2" : "mt-4" }, [
      h(
        "div",
        {
          key: "rep",
          className:
            "inline-flex min-h-[44px] w-full items-center justify-center gap-2 rounded-2xl border border-rose-500/40 bg-white px-4 text-sm font-semibold text-rose-700 dark:border-rose-400/40 dark:bg-night-900/40 dark:text-rose-200"
        },
        [h(AlertTriangle, { key: "i", className: "h-4 w-4" }), "Report an Issue"]
      ),
      variant === "buyer"
        ? h(
            Link,
            {
              key: "ro",
              to: "/",
              className:
                "inline-flex min-h-[44px] w-full items-center justify-center rounded-2xl bg-purple-700 px-4 text-sm font-semibold text-white shadow-sm hover:bg-purple-800"
            },
            "Reorder"
          )
        : null
    ])
  ]);
}

/**
 * @param {{ variant: "buyer" | "vendor" }} props
 */
function ReportPanelInner({ variant }) {
  const { accessToken } = useAuth();
  const { toast } = useNotice();
  const [searchParams] = useSearchParams();
  const fileRef = useRef(null);

  const problemOptions = variant === "vendor" ? VENDOR_PROBLEMS : BUYER_PROBLEMS;

  const [category, setCategory] = useState("");
  const [description, setDescription] = useState("");
  const [targetType, setTargetType] = useState("other");
  const [targetId, setTargetId] = useState("");
  const [evidenceUrls, setEvidenceUrls] = useState([]);
  const [evidenceUploading, setEvidenceUploading] = useState(false);
  const [submitErr, setSubmitErr] = useState("");
  const [submitting, setSubmitting] = useState(false);

  const [contextOrder, setContextOrder] = useState(null);
  const [contextProduct, setContextProduct] = useState(null);
  const [contextProducts, setContextProducts] = useState({});
  const [contextLoading, setContextLoading] = useState(false);
  const [contextErr, setContextErr] = useState("");
  const [refreshNonce, setRefreshNonce] = useState(0);

  const orderFromParam = searchParams.get("order");
  const productFromParam = searchParams.get("product");
  const userFromParam = searchParams.get("user");

  useEffect(() => {
    if (productFromParam) {
      setTargetType("product");
      setTargetId(productFromParam);
    } else if (orderFromParam) {
      setTargetType("order");
      setTargetId(orderFromParam);
    } else if (userFromParam) {
      setTargetType("user");
      setTargetId(userFromParam);
    } else {
      setTargetType("other");
      setTargetId("");
    }
  }, [productFromParam, orderFromParam, userFromParam]);

  useEffect(() => {
    if (!accessToken || targetType !== "order" || !targetId) {
      setContextOrder(null);
      setContextProducts({});
      return;
    }
    let cancelled = false;
    setContextLoading(true);
    setContextErr("");
    (async () => {
      try {
        const d = await apiFetch(`/api/orders/${targetId}`, {
          headers: { Authorization: `Bearer ${accessToken}` }
        });
        if (cancelled || !d.order) return;
        setContextOrder(d.order);
        const pids = [...new Set((d.order.items || []).map((it) => it.productId).filter(Boolean))];
        const map = {};
        for (const pid of pids) {
          try {
            const pr = await apiFetch(`/api/products/${pid}`);
            if (pr.product) map[pid] = pr.product;
          } catch {
            /* ignore */
          }
        }
        if (!cancelled) setContextProducts(map);
      } catch (ex) {
        if (!cancelled) {
          setContextOrder(null);
          setContextProducts({});
          setContextErr(ex.message || "Could not load order details for this report.");
        }
      } finally {
        if (!cancelled) setContextLoading(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [accessToken, targetType, targetId, refreshNonce]);

  useEffect(() => {
    if (!targetId || targetType !== "product") {
      setContextProduct(null);
      return;
    }
    let cancelled = false;
    (async () => {
      try {
        const d = await apiFetch(`/api/products/${targetId}`);
        if (!cancelled && d.product) setContextProduct(d.product);
      } catch {
        if (!cancelled) setContextProduct(null);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [targetId, targetType]);

  const addEvidenceFile = async (file) => {
    if (!file || !accessToken) return;
    if (evidenceUrls.length >= 3) {
      setSubmitErr("You can attach at most 3 images.");
      return;
    }
    const ok = /^image\/(jpeg|png|webp)$/i.test(file.type) || /\.(jpe?g|png|webp)$/i.test(file.name);
    if (!ok) {
      setSubmitErr("Use PNG, JPG, or WebP (max 5 MB each).");
      return;
    }
    if (file.size > 5 * 1024 * 1024) {
      setSubmitErr("Each file must be 5 MB or smaller.");
      return;
    }
    setSubmitErr("");
    setEvidenceUploading(true);
    try {
      const fd = new FormData();
      fd.append("file", file);
      const res = await fetch(`${getApiBase()}/api/uploads/report-evidence`, {
        method: "POST",
        headers: { Authorization: `Bearer ${accessToken}` },
        body: fd,
        credentials: "include"
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok) {
        const msg = data?.error?.message || data?.message || `Upload failed (${res.status})`;
        throw new Error(msg);
      }
      if (data.url) setEvidenceUrls((prev) => [...prev, data.url].slice(0, 3));
    } catch (ex) {
      setSubmitErr(ex.message || "Upload failed.");
    } finally {
      setEvidenceUploading(false);
    }
  };

  const onSubmit = async (e) => {
    e.preventDefault();
    setSubmitErr("");
    if (!accessToken) return;
    if (!category) {
      setSubmitErr("Please select an issue type.");
      return;
    }
    if (String(description).trim().length < 10) {
      setSubmitErr("Please describe the issue in at least 10 characters.");
      return;
    }
    setSubmitting(true);
    try {
      await apiFetch("/api/reports", {
        method: "POST",
        headers: { Authorization: `Bearer ${accessToken}` },
        json: {
          category,
          description: description.trim(),
          targetType,
          targetId: String(targetId).trim() || undefined,
          evidenceUrls: evidenceUrls.length ? evidenceUrls : undefined
        }
      });
      toast("Report submitted. Our team will review it.", { variant: "success" });
      setDescription("");
      setCategory("");
      setEvidenceUrls([]);
    } catch (ex) {
      setSubmitErr(ex.message || "Could not submit report.");
    } finally {
      setSubmitting(false);
    }
  };

  const placeholderOption = h("option", { key: "ph", value: "" }, "Select issue type");
  const catOptions = [placeholderOption, ...problemOptions.map((c) => h("option", { key: c.value, value: c.value }, c.label))];

  const pageTitle = variant === "vendor" ? "Report a Buyer / Issue" : "Report an Issue";
  const pageSub =
    variant === "vendor"
      ? "We will review your report and take action if needed."
      : "We will review your report and get back to you.";

  // Inline order/product context (rendered inside the form, between description and upload)
  const lines = (contextOrder && contextOrder.items) || [];
  const myLines =
    variant === "vendor"
      ? lines
      : lines;
  const firstLine = myLines[0];
  const firstSellerId = firstLine ? String(firstLine.sellerId || "") : "";
  const sellerContacts = (contextOrder && contextOrder.sellerContacts) || [];
  const vendorContact =
    firstSellerId && Array.isArray(sellerContacts)
      ? sellerContacts.find((s) => String(s.id) === firstSellerId) || sellerContacts[0]
      : null;
  const buyer = (contextOrder && contextOrder.buyerContact) || null;
  const firstProduct = firstLine && firstLine.productId ? contextProducts[String(firstLine.productId)] : null;
  const firstImg = firstProduct && firstProduct.imageUrls && firstProduct.imageUrls[0] ? firstProduct.imageUrls[0] : null;

  const inlineContextBlock = contextOrder
    ? h("div", { key: "inline-ctx", className: "space-y-3 rounded-2xl border border-slate-100 bg-slate-50/60 p-3 text-sm dark:border-white/5 dark:bg-white/[0.02]" }, [
        h("div", { key: "oid", className: "flex items-center justify-between" }, [
          h("span", { className: "text-xs font-semibold uppercase tracking-wider text-slate-500" }, "Order ID"),
          h("span", { className: "font-mono text-xs font-semibold text-slate-900 dark:text-white" }, `#${orderRef(contextOrder.id)}`)
        ]),
        firstLine
          ? h("div", { key: "pr", className: "flex items-center gap-3" }, [
              firstImg
                ? h(
                    "div",
                    { className: "h-12 w-12 shrink-0 overflow-hidden rounded-xl border border-slate-200 bg-white dark:border-white/10" },
                    h("img", { src: firstImg, alt: "", className: "h-full w-full object-cover" })
                  )
                : h(
                    "div",
                    { className: "flex h-12 w-12 shrink-0 items-center justify-center rounded-xl border border-slate-200 bg-white dark:border-white/10" },
                    h(Package, { className: "h-5 w-5 text-slate-400" })
                  ),
              h("p", { className: "min-w-0 flex-1 truncate text-sm font-medium text-slate-800 dark:text-slate-100" }, firstLine.name)
            ])
          : null,
        variant === "buyer" && vendorContact
          ? h("div", { key: "vd", className: "flex items-center gap-3" }, [
              h(
                "div",
                { className: "flex h-9 w-9 items-center justify-center rounded-full bg-purple-500/15 text-purple-700 dark:text-purple-200" },
                h(Store, { className: "h-4 w-4" })
              ),
              h("div", { className: "min-w-0 flex-1" }, [
                h("p", { className: "truncate text-sm font-medium text-slate-800 dark:text-slate-100" }, vendorContact.displayName || "Seller"),
                h("p", { className: "text-xs text-slate-500" }, "Vendor")
              ])
            ])
          : null,
        variant === "vendor" && buyer
          ? h("div", { key: "by", className: "flex items-center gap-3" }, [
              h(
                "div",
                { className: "flex h-9 w-9 items-center justify-center rounded-full bg-violet-500/15 text-violet-700 dark:text-violet-200" },
                h(UserIcon, { className: "h-4 w-4" })
              ),
              h("div", { className: "min-w-0 flex-1" }, [
                h("p", { className: "truncate text-sm font-medium text-slate-800 dark:text-slate-100" }, buyer.displayName || buyer.email || "Buyer"),
                h("p", { className: "text-xs text-slate-500" }, "Customer")
              ])
            ])
          : null
      ].filter(Boolean))
    : contextProduct
      ? h(
          "div",
          {
            key: "inline-pr",
            className: "rounded-2xl border border-slate-100 bg-slate-50/60 p-3 text-sm dark:border-white/5 dark:bg-white/[0.02]"
          },
          h("div", { className: "flex items-center gap-3" }, [
            contextProduct.imageUrls && contextProduct.imageUrls[0]
              ? h(
                  "div",
                  { className: "h-12 w-12 shrink-0 overflow-hidden rounded-xl border border-slate-200 bg-white dark:border-white/10" },
                  h("img", { src: contextProduct.imageUrls[0], alt: "", className: "h-full w-full object-cover" })
                )
              : h(
                  "div",
                  { className: "flex h-12 w-12 shrink-0 items-center justify-center rounded-xl border border-slate-200 bg-white dark:border-white/10" },
                  h(Package, { className: "h-5 w-5 text-slate-400" })
                ),
            h("div", { className: "min-w-0 flex-1" }, [
              h("p", { className: "text-xs font-semibold uppercase tracking-wider text-slate-500" }, "Product"),
              h("p", { className: "truncate text-sm font-medium text-slate-800 dark:text-slate-100" }, contextProduct.name || contextProduct.title || "Product")
            ])
          ])
        )
      : null;

  // Two-card grid: Order Details (left) + Report Form (right). On smaller screens, stacks vertically.
  const showLeft = Boolean(contextOrder || contextLoading || contextErr);
  return h("div", { className: "mx-auto w-full max-w-6xl px-0 py-6 sm:py-8" }, [
    h("div", { key: "grid", className: showLeft ? "grid grid-cols-1 gap-6 lg:grid-cols-2" : "mx-auto w-full max-w-2xl" }, [
      showLeft
        ? h(OrderDetailsCard, {
            key: "left",
            variant,
            order: contextOrder,
            products: contextProducts,
            loading: contextLoading,
            err: contextErr,
            onRefresh: () => setRefreshNonce((n) => n + 1)
          })
        : null,
      h(
        GlassPanel,
        {
          key: "right",
          className: "!border-white/10 !p-5 sm:!p-6"
        },
        [
          h("div", { key: "ft", className: "mb-4 flex items-center gap-3" }, [
            h(
              "div",
              {
                className:
                  "flex h-10 w-10 shrink-0 items-center justify-center rounded-2xl bg-rose-500/15 text-rose-700 dark:text-rose-200"
              },
              h(AlertTriangle, { className: "h-5 w-5" })
            ),
            h("h2", { className: "font-display text-lg font-bold text-slate-900 dark:text-white" }, pageTitle)
          ]),
          h("form", { key: "form", className: "space-y-4", onSubmit }, [
            h(
              Field,
              { label: "What seems to be the problem?" },
              h(SelectInput, {
                value: category,
                onChange: (e) => setCategory(e.target.value),
                required: true,
                className: "!border-slate-200 !bg-white dark:!border-white/10 dark:!bg-night-900/40"
              }, catOptions)
            ),
            h(Field, { key: "desc", label: "Please describe the issue *" }, h(TextArea, {
              value: description,
              onChange: (e) => setDescription(e.target.value.slice(0, 4000)),
              rows: 5,
              required: true,
              placeholder: "Explain what happened in detail…",
              className: "min-h-[120px] !border-slate-200 dark:!border-white/10"
            })),

            inlineContextBlock,

            h("div", { key: "up", className: "space-y-2" }, [
              h(
                "p",
                { className: "text-sm font-semibold text-slate-700 dark:text-slate-200" },
                "Upload evidence (optional)"
              ),
              h(
                "button",
                {
                  type: "button",
                  disabled: evidenceUploading || evidenceUrls.length >= 3,
                  onClick: () => fileRef.current?.click(),
                  onDragOver: (e) => {
                    e.preventDefault();
                    e.stopPropagation();
                  },
                  onDrop: (e) => {
                    e.preventDefault();
                    e.stopPropagation();
                    const f2 = e.dataTransfer.files && e.dataTransfer.files[0];
                    if (f2) addEvidenceFile(f2);
                  },
                  className:
                    "flex w-full flex-col items-center justify-center gap-2 rounded-2xl border-2 border-dashed border-slate-200 bg-slate-50/40 px-4 py-8 text-center transition hover:border-purple-400 hover:bg-purple-50/40 disabled:opacity-50 dark:border-white/10 dark:bg-white/[0.02]"
                },
                [
                  evidenceUploading
                    ? h(Loader2, { key: "ld", className: "h-8 w-8 animate-spin text-slate-500" })
                    : h(Upload, { key: "ic", className: "h-8 w-8 text-slate-500" }),
                  h("p", { key: "t1", className: "text-sm font-medium text-slate-700 dark:text-slate-200" }, "Click to upload or drag and drop"),
                  h("p", { key: "t2", className: "text-xs text-slate-500" }, "PNG, JPG up to 5MB")
                ]
              ),
              h("input", {
                ref: fileRef,
                type: "file",
                accept: "image/png,image/jpeg,image/webp",
                className: "hidden",
                onChange: (e) => {
                  const f2 = e.target.files && e.target.files[0];
                  e.target.value = "";
                  if (f2) addEvidenceFile(f2);
                }
              }),
              evidenceUrls.length
                ? h("div", { key: "thumbs", className: "flex flex-wrap gap-2" }, evidenceUrls.map((url, i) =>
                    h("div", { key: url, className: "group relative" }, [
                      h("img", { src: url, alt: "", className: "h-16 w-16 rounded-xl border border-slate-200 object-cover dark:border-white/10" }),
                      h(
                        "button",
                        {
                          type: "button",
                          "aria-label": "Remove",
                          className:
                            "absolute -right-1.5 -top-1.5 flex h-6 w-6 items-center justify-center rounded-full bg-rose-600 text-white shadow-md opacity-0 transition group-hover:opacity-100",
                          onClick: () => setEvidenceUrls((u) => u.filter((_, j) => j !== i))
                        },
                        h(Trash2, { className: "h-3 w-3" })
                      )
                    ])
                  ))
                : null
            ]),

            submitErr ? h(InlineNotice, { key: "err", variant: "error", onDismiss: () => setSubmitErr("") }, submitErr) : null,
            h(
              "button",
              {
                key: "sub",
                type: "submit",
                disabled: submitting,
                className:
                  "tap-target inline-flex w-full min-h-[48px] items-center justify-center gap-2 rounded-2xl bg-[#6D28D9] px-5 text-sm font-semibold text-white shadow-md shadow-purple-900/20 transition-all hover:bg-violet-800 disabled:opacity-60 dark:hover:bg-violet-600"
              },
              [
                submitting ? h(Loader2, { key: "ld", className: "h-4 w-4 animate-spin" }) : h(Send, { key: "i", className: "h-4 w-4" }),
                h("span", { key: "t" }, "Submit Report")
              ]
            ),
            h(
              "p",
              { key: "fine", className: "text-center text-xs text-slate-500 dark:text-slate-400" },
              pageSub
            )
          ].filter(Boolean))
        ]
      )
    ])
  ]);
}

